function impactHop(ball){if(!ball.hit||!state||ball.hit.kind==='ground')return 0;const age=state.time-ball.hit.time;if(age<0||age>.32)return 0;return Math.sin(age/.32*Math.PI)*(.13+ball.hit.power*.23)}
function updateImpacts(t){if(!impactGroup)return;
 for(const v of visuals){const hit=v.ball.hit;if(!hit||hit.serial===v.hitSerial)continue;v.hitSerial=hit.serial;if(mode==='setup'||t-hit.time>.4)continue;const p=point(hit.s,hit.u,.12);projection.copy(p).project(camera);if(Math.abs(projection.x)>1.2||Math.abs(projection.y)>1.2||projection.z>1||camera.position.distanceTo(p)>85)continue;if(mode==='race'&&!paused)music.impact(hit.power,Math.max(-1,Math.min(1,projection.x)),hit.kind);const slot=impactPool[impactCursor++%impactPool.length];slot.at=hit.time;slot.power=hit.power;slot.group.position.copy(p);slot.directions=Array.from({length:8},(_,k)=>{const a=k*Math.PI/4+hit.serial*.7;return {x:Math.cos(a)*(2+hit.power*2)+hit.nu*1.5,z:Math.sin(a)*(2+hit.power*2)-hit.ns*1.5,y:2.3+(k%3)*.6}});}
 for(const slot of impactPool){const age=t-slot.at,life=.43;slot.group.visible=mode!=='setup'&&age>=0&&age<life;if(!slot.group.visible)continue;const fade=1-age/life;slot.ring.scale.setScalar(.5+age*5);slot.ring.material.opacity=fade*.8;slot.flash.scale.setScalar(Math.max(.05,fade)*(1+slot.power));slot.flash.material.opacity=Math.max(0,1-age/.16)*.95;slot.sparks.material.opacity=fade;const positions=slot.sparks.geometry.attributes.position;slot.directions.forEach((d,i)=>positions.setXYZ(i,d.x*age,Math.max(.05,.25+d.y*age-5*age*age),d.z*age));positions.needsUpdate=true;}
}
function createMarbles(){resetImpacts();disposeGroup(marbleGroup);marbleGroup=new T.Group();scene.add(marbleGroup);$('labels').replaceChildren();$('ranking').replaceChildren();rankRows.clear();visuals=[];const count=state.balls.length,bodyGeometry=new T.SphereGeometry(M.RADIUS,16,12),glow=new T.InstancedBufferAttribute(new Float32Array(count*3),3);bodyGeometry.setAttribute('instanceGlow',glow);const bodyMaterial=material(0xffffff,{roughness:.17,metalness:.28});bodyMaterial.onBeforeCompile=shader=>{shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nattribute vec3 instanceGlow; varying vec3 vInstanceGlow;').replace('#include <begin_vertex>','#include <begin_vertex>\nvInstanceGlow = instanceGlow;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vInstanceGlow;').replace('vec3 totalEmissiveRadiance = emissive;','vec3 totalEmissiveRadiance = emissive + vInstanceGlow;')};bodyMaterial.customProgramCacheKey=()=> 'spacepick-instanced-glow-v1';
 const body=new T.InstancedMesh(bodyGeometry,bodyMaterial,count),stripe=new T.InstancedMesh(new T.TorusGeometry(M.RADIUS*.993,.034,4,24),material(0xffffff,{roughness:.24}),count),gloss=new T.InstancedMesh(new T.SphereGeometry(.095,6,4),new T.MeshBasicMaterial({color:0xffffff}),count);for(const batch of [body,stripe,gloss]){batch.instanceMatrix.setUsage(T.DynamicDrawUsage);batch.frustumCulled=false;marbleGroup.add(batch)}const stripeLocal=new T.Matrix4().makeRotationX(Math.PI/2.7),glossLocal=new T.Matrix4().makeTranslation(-.18,.31,.27);marbleBatches={body,stripe,gloss,glow,stripeLocal,glossLocal,matrix:new T.Matrix4(),boost:new T.Color(0x1677bb).multiplyScalar(.8),slow:new T.Color(0x6b239a).multiplyScalar(.8)};
 for(const ball of state.balls){const transform=new T.Object3D(),label=document.createElement('div');label.className='ball-label';label.textContent=ball.label;label.hidden=true;label.style.left='0';label.style.top='0';$('labels').append(label);visuals.push({ball,mesh:transform,label,color:new T.Color(ball.color),previous:ball.s,hitSerial:0,labelText:ball.label})}}
function updateMarbles(dt){if(!marbleBatches)return;const batch=marbleBatches,now=performance.now(),updateLabels=now>=labelNextUpdate;if(updateLabels)labelNextUpdate=now+50;let count=0,labels=0;
 for(const v of visuals){const b=v.ball;if(b.done){v.label.hidden=true;continue}const alpha=paused||mode!=='race'||countdown>0?1:renderAlpha,s=b.prevS===undefined?b.s:b.prevS+(b.s-b.prevS)*alpha,u=b.prevU===undefined?b.u:b.prevU+(b.u-b.prevU)*alpha,lift=b.verticalEnabled?(b.prevLift??b.lift)+((b.lift||0)-(b.prevLift??b.lift))*alpha:0,boosted=b.boostUntil>state.time,slowed=b.slowUntil>state.time;const age=b.hit?.kind==='ground'?state.time-b.hit.time:1,squash=age>=0&&age<.16?Math.sin(age/.16*Math.PI)*.17*b.hit.power:0;v.mesh.position.set(M.lateral(s,u),M.height(s)+M.RADIUS+.06+lift+impactHop(b)-squash*M.RADIUS,-s);v.mesh.rotation.x-=(s-v.previous)/M.RADIUS;v.mesh.rotation.z-=b.vu*dt/M.RADIUS;v.previous=s;v.mesh.scale.set(1+squash*.5,1-squash,1+squash*.5);const distanceSq=camera.position.distanceToSquared(v.mesh.position);if(distanceSq>32400){v.label.hidden=true;continue}v.mesh.updateMatrix();batch.body.setMatrixAt(count,v.mesh.matrix);batch.body.setColorAt(count,v.color);batch.matrix.multiplyMatrices(v.mesh.matrix,batch.stripeLocal);batch.stripe.setMatrixAt(count,batch.matrix);batch.matrix.multiplyMatrices(v.mesh.matrix,batch.glossLocal);batch.gloss.setMatrixAt(count,batch.matrix);const color=boosted?batch.boost:slowed?batch.slow:null;batch.glow.setXYZ(count,color?.r||0,color?.g||0,color?.b||0);count++;
 if(updateLabels){projection.copy(v.mesh.position);projection.y+=1.1;projection.project(camera);const show=mode==='race'&&projection.z<1&&projection.z>0&&Math.abs(projection.x)<=1&&Math.abs(projection.y)<=1&&distanceSq<4900&&(visuals.length<=60||distanceSq<3600)&&labels<48;v.label.hidden=!show;if(show){labels++;const text=b.label+(boosted?' ⚡':slowed?' ❄':'');if(text!==v.labelText){v.label.textContent=text;v.labelText=text}}}if(!v.label.hidden){if(!updateLabels){projection.copy(v.mesh.position);projection.y+=1.1;projection.project(camera)}v.label.style.transform='translate3d('+((projection.x*.5+.5)*innerWidth)+'px,'+((-projection.y*.5+.5)*innerHeight)+'px,0) translate(-50%,-100%)'}}
 for(const mesh of [batch.body,batch.stripe,batch.gloss]){mesh.count=count;mesh.instanceMatrix.needsUpdate=true}if(batch.body.instanceColor)batch.body.instanceColor.needsUpdate=true;batch.glow.needsUpdate=true;
}
function updateObstacles(t){for(const {obstacle:o,mesh:obj} of obstacleMeshes){if(o.type==='slider'){const p=M.obstaclePose(o,t);obj.position.copy(point(p.s,p.u));continue}const {angle}=M.rotorPose(o,t);const a=point(o.s-Math.sin(angle)*o.r,o.u-Math.cos(angle)*o.r,.7),b=point(o.s+Math.sin(angle)*o.r,o.u+Math.cos(angle)*o.r,.7);obj.position.copy(a).add(b).multiplyScalar(.5);obj.quaternion.setFromUnitVectors(new T.Vector3(0,1,0),b.sub(a).normalize())}}
function updateCamera(dt,elapsed){let s,target,position;if(mode==='setup'){s=115;position=point(s-15,36+Math.sin(elapsed*.09)*7,30);target=point(s+25,0,0);camera.position.lerp(position,1-Math.exp(-dt*2));cameraAim.lerp(target,1-Math.exp(-dt*2))}else if(mode==='race'&&capsule&&state.time<2.8){const s=capsule.center;position=point(s-24-capsule.depth*.3,20,24+capsule.depth*.15,0);target=point(s,0,6.5,0);camera.position.lerp(position,1-Math.exp(-dt*3));cameraAim.lerp(target,1-Math.exp(-dt*3))}else{let leader=-Infinity;for(const b of state.balls)if(!b.done&&b.s>leader)leader=b.s;leader=leader===-Infinity?M.LENGTH:Math.max(0,leader);follow+=(leader-follow)*(1-Math.exp(-dt*2));s=follow;if(viewMode===0){position=point(s-20,14,18+Math.max(0,M.outerWidth(s)-9)*1.25,0);target=point(s+12,0,0,0)}else if(viewMode===1){position=point(s-4,1,34,0);target=point(s+9,0,0,0)}else{position=point(s-25,-18,22,0);target=point(s+10,0,0,0)}camera.position.lerp(position,1-Math.exp(-dt*3));cameraAim.lerp(target,1-Math.exp(-dt*3))}camera.lookAt(cameraAim);camera.updateMatrixWorld()}
function renderRows(){ $('entryRows').replaceChildren();config.forEach((item,i)=>{const row=document.createElement('div');row.className='entry-row';const dot=document.createElement('span');dot.className='ball-dot';dot.style.background=palette[i%palette.length];const name=document.createElement('input');name.value=item.name;name.maxLength=16;name.setAttribute('aria-label','공 '+(i+1)+' 이름');name.oninput=()=>{item.name=name.value;summary()};const count=document.createElement('input');count.type='number';count.min=1;count.max=500;count.value=item.count;count.setAttribute('aria-label','공 '+(i+1)+' 개수');count.oninput=()=>{item.count=count.value;summary()};row.append(dot,name,count);$('entryRows').append(row)});summary()}
function summary(){const total=config.reduce((n,item)=>n+Number(item.count||0),0);$('totalCount').textContent=total;$('pickSummary').textContent=$('pickCount').value||0;$('pickCount').max=Math.min(total,500);$('error').textContent=''}
function settings(){const n=Number($('typeCount').value);if(!Number.isInteger(n)||n<1||n>500||n!==config.length)throw Error('공 종류 수는 1~500 사이 정수로 입력하세요.');const entries=[];config.forEach((item,i)=>{const label=item.name.trim(),count=Number(item.count);if(!label||label.length>16)throw Error((i+1)+'번 공 이름은 1~16자로 입력하세요.');if(!Number.isInteger(count)||count<1||count>500)throw Error((i+1)+'번 공 개수는 1~500 사이 정수로 입력하세요.');for(let copy=1;copy<=count;copy++)entries.push({label,copy,copies:count,color:palette[i%palette.length]})});if(entries.length<2||entries.length>500)throw Error('전체 공 개수를 2~500개로 설정하세요.');const wanted=Number($('pickCount').value);if(!Number.isInteger(wanted)||wanted<1||wanted>entries.length)throw Error('뽑을 공 개수는 1개 이상, 전체 공 개수 이하로 입력하세요.');return {entries,wanted}}
function start(){let options;try{options=settings()}catch(e){$('error').textContent=e.message;return}if(music.enabled)music.unlock();state=M.create(options.entries);picks=options.wanted;buildTrack(state.obstacles,state.events,state.forks);capsule.prepare(state.balls);createMarbles();mode='race';paused=false;countdown=3;lastCountdownBeep=3;music.countdown();music.beep(3);speed=1;follow=0;accumulator=0;lastArrival=0;lastHud=-1;lastSector=-1;eventNotices.clear();$('setup').hidden=true;$('raceScreen').hidden=false;$('results').hidden=true;$('countdown').hidden=false;$('speed').textContent='1×';$('pause').textContent='Ⅱ';$('pause').setAttribute('aria-label','일시정지');$('skip').disabled=false;$('skip').textContent='최종 결과 바로 보기';$('pause').disabled=false;$('speed').disabled=false;$('announcement').classList.remove('visible');$('trackName').textContent=aurora.name;$('targetInfo').textContent='먼저 도착한 '+picks+'개 공 당첨';document.body.style.overflow='hidden';viewMode=0;$('cameraText').textContent='뒤에서 진행 방향을 보는 카메라';camera.position.copy(point(capsule.center-24-capsule.depth*.3,20,24+capsule.depth*.15,0));cameraAim.copy(point(capsule.center,0,6.5,0));window.scrollTo(0,0);$('back').focus({preventScroll:true});updateHUD()}
function edit(){music.enterSetup();capsule?.hide();resetImpacts();mode='setup';paused=false;$('setup').hidden=false;$('raceScreen').hidden=true;$('results').hidden=true;$('labels').replaceChildren();visuals=[];disposeGroup(marbleGroup);marbleGroup=null;marbleBatches=null;document.body.style.overflow='';$('start').focus({preventScroll:true})}
function announce(text){$('announcement').textContent=text;$('announcement').classList.add('visible');noticeUntil=performance.now()+4000}
function ordered(){return [...state.finished,...state.balls.filter(b=>!b.done).sort((a,b)=>b.s-a.s)]}
function updateHUD(){const ranks=ordered(),scroll=$('ranking').scrollTop;let cursor=$('ranking').firstElementChild;ranks.forEach((b,i)=>{let entry=rankRows.get(b.id);if(!entry){const row=document.createElement('div'),num=document.createElement('span'),dot=document.createElement('i'),name=document.createElement('span'),tag=document.createElement('small');num.className='position';dot.style.background=b.color;name.className='rank-name';name.textContent=b.label;row.dataset.ballId=b.id;row.append(num,dot,name,tag);entry={row,num,dot,name,tag};rankRows.set(b.id,entry)}const {row,num,tag}=entry;const qualified=b.done&&i<picks;row.className='rank-row'+(qualified?' qualified':b.done?' arrived':'');row.dataset.ballId=b.id;row.setAttribute('aria-label',(i+1)+'위 '+b.label+(qualified?' 당첨 확정':b.done?' 도착':' 경주 중'));const rankText=String(i+1).padStart(2,'0');if(num.textContent!==rankText)num.textContent=rankText;const status=qualified?'★ 당첨':b.done?'도착':state.time<(b.landAt||0)?'출발 준비':b.boostUntil>state.time?'⚡ 가속':b.slowUntil>state.time?'❄ 감속':'경주 중';if(tag.textContent!==status)tag.textContent=status;if(row===cursor)cursor=cursor.nextElementSibling;else $('ranking').insertBefore(row,cursor)});$('ranking').scrollTop=scroll;$('targetInfo').textContent='당첨 확정 '+Math.min(state.finished.length,picks)+' / '+picks+'개';$('arrivals').textContent=state.finished.length+' / '+state.balls.length;const leader=Math.max(state.complete?M.LENGTH:0,...state.balls.filter(b=>!b.done).map(b=>b.s));const sector=M.sectorAt(leader);$('sectorName').textContent=sector.name;$('difficulty').textContent='난이도'+' '+ '●'.repeat(sector.level)+'○'.repeat(5-sector.level);if(lastSector!==sector.level){lastSector=sector.level;if(sector.level>1)announce('SECTOR 0'+sector.level+' · '+sector.name)}const t=Math.floor(state.time);$('timer').textContent=String(Math.floor(t/60)).padStart(2,'0')+':'+String(t%60).padStart(2,'0');$('progress').style.width=Math.max(0,Math.min(100,(state.finished.length?M.LENGTH:Math.max(...state.balls.map(b=>b.s)))/M.LENGTH*100))+'%';$('raceState').textContent=mode==='resolving'?'CALCULATING RESULTS':paused?'PAUSED':countdown>0?'STARTING GRID':state.complete?'RACE COMPLETE':'RACE IN PROGRESS';if(state.finished.length>lastArrival){const winner=state.finished[0];if(lastArrival<picks&&state.finished.length>=picks)announce('당첨 공 '+picks+'개 선정 완료! 순위표에서 확인하세요.');else if(lastArrival===0)announce('첫 번째 도착! '+winner.label);lastArrival=state.finished.length}}
async function resolveResult(){if(mode!=='race')return;const current=state;mode='resolving';paused=true;music.pause(true);countdown=0;$('countdown').hidden=true;$('skip').disabled=true;$('skip').textContent='결과 계산 중…';$('pause').disabled=true;$('speed').disabled=true;announce('현재 레이스를 빠르게 진행해 최종 결과를 확인합니다.');await new Promise(requestAnimationFrame);while(!current.complete&&mode==='resolving'&&state===current){const began=performance.now();do{M.step(current,1/120)}while(!current.complete&&performance.now()-began<12);updateHUD();await new Promise(requestAnimationFrame)}if(mode==='resolving'&&state===current){paused=false;updateHUD();finish()}}
function finish(){music.results();capsule?.hide();mode='results';$('results').hidden=false;$('resultDetail').textContent=aurora.name+' · '+state.balls.length+'개 구슬 완주 · '+state.time.toFixed(1)+'초';$('winners').replaceChildren();state.finished.slice(0,picks).forEach((b,i)=>{const row=document.createElement('div');row.className='winner-row';const rank=document.createElement('b');rank.textContent=String(i+1).padStart(2,'0');const dot=document.createElement('span');dot.className='ball-dot';dot.style.background=b.color;const name=document.createElement('div');name.className='winner-name';name.textContent=b.label;const small=document.createElement('small');small.textContent=b.finishTime.toFixed(2)+'초'+(b.copies>1?' · 동일 이름 공 '+b.copy+'/'+b.copies:'');name.append(small);row.append(rank,dot,name);$('winners').append(row)});$('allRanking').replaceChildren();state.finished.forEach(b=>{const li=document.createElement('li');li.textContent=b.label+' · '+b.finishTime.toFixed(2)+'초';$('allRanking').append(li)});$('copy').textContent='결과 복사';$('replay').focus()}
function advanceCountdown(dt){countdown=Math.max(0,countdown-dt);const n=Math.ceil(countdown);if(n>0&&n!==lastCountdownBeep){lastCountdownBeep=n;music.beep(n)}$('countdown').textContent=n||'GO!';if(!countdown){$('countdown').hidden=true;music.startRace()}}
function frame(now){const dt=Math.min((now-last)/1000,.05)||.016;last=now;if(mode==='race'&&!paused){if(countdown>0){advanceCountdown(dt)}else{if(music.phase==='countdown')music.startRace();accumulator+=dt*speed;let loops=0;while(accumulator>=1/120&&loops++<16&&!state.complete){M.step(state,1/120);accumulator-=1/120}if(state.complete){updateHUD();finish()}}}renderAlpha=mode==='race'&&!paused&&countdown<=0?Math.min(1,accumulator*120):1;if(capsule&&mode!=='setup')capsule.update(state?.time||0,countdown);updateObstacles(state&&mode!=='setup'?state.time:now/1000);updateCamera(dt,now/1000);updateSpaceEvents(state&&mode!=='setup'?state.time:0);updateMarbles(paused?0:dt);updateImpacts(state?.time||0);if(mode==='race'&&(now-lastHud>250||state.finished.length>lastArrival)){updateHUD();lastHud=now}if(now>noticeUntil)$('announcement').classList.remove('visible');renderer.render(scene,camera);requestAnimationFrame(frame)}
$('typeCount').oninput=()=>{const n=Number($('typeCount').value);if(!Number.isInteger(n)||n<1||n>500)return;while(config.length<n)config.push({name:String(config.length+1),count:1});config.length=n;renderRows()};$('skip').onclick=resolveResult;$('pickCount').oninput=summary;$('start').onclick=start;$('replay').onclick=start;$('back').onclick=edit;$('edit').onclick=edit;
$('pause').onclick=()=>{paused=!paused;music.pause(paused);$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'계속하기':'일시정지');updateHUD()};$('speed').onclick=()=>{speed=speed===1?2:speed===2?3:1;$('speed').textContent=speed+'×'};$('cameraMode').onclick=()=>{viewMode=(viewMode+1)%3;$('cameraText').textContent=['뒤에서 진행 방향을 보는 카메라','위에서 내려다보는 카메라','뒤쪽 대각선에서 따라가는 카메라'][viewMode]};
$('copy').onclick=async()=>{const text=state.finished.slice(0,picks).map((b,i)=>(i+1)+'등 '+b.label+' ('+b.finishTime.toFixed(2)+'초)').join('\n');try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(text);else{const field=document.createElement('textarea');field.value=text;field.style.cssText='position:fixed;left:-9999px';document.body.append(field);field.select();if(!document.execCommand('copy'))throw Error('copy');field.remove()}$('copy').textContent='복사 완료 ✓'}catch{$('copy').textContent='복사 실패 · 순위를 선택해 복사하세요'}};
